d['secs']=[('¿Cuáles son los errores más comunes al calcular un codice fiscale?',['La tabla recoge los diez errores más frecuentes, con la forma de detectar cada uno. Los ejemplos usan el código de muestra <code>RSSMRA85T10H501O</code>.',tbl(['Error','Cómo detectarlo','Cómo evitarlo'],rows)]),
 ('¿Por qué mi código calculado difiere del de mi tarjeta sanitaria?',[f'Los motivos más frecuentes son la grafía de los datos y la omocodia. {a(PMI,"Pmi.it")} (en italiano) cita espacios, apóstrofos, nombres dobles, caracteres especiales y nacimiento en el extranjero entre las causas. Un código con letras donde deberían ir cifras es una variante de omocodia.']),
 ('¿Cómo se comprueba un código después de calcularlo?',['Compruébalo en tres pasos, del más rápido al más seguro.',ol(['Pásalo por la <a href="{{p:verify}}">comprobación</a>: detecta estructura, fecha y letra de control erróneas.','Léelo con el <a href="{{p:inverse}}">descifrador</a> para ver que sexo, fecha y lugar son los esperados.',f'Compáralo con tu tarjeta sanitaria o con el {a(V,"servicio de la Agenzia delle Entrate")} (en italiano).'])]),
 ('¿Qué errores detecta una comprobación formal y cuáles no?',['Detecta estructura errónea, mes o día imposibles y una letra de control equivocada. No detecta un lugar erróneo pero plausible, un nombre escrito de otra forma ni un código que nadie posee. Para eso hace falta un documento oficial. Mira <a href="{{g:verifica-formale-e-verifica-ufficiale}}">verificación formal y oficial</a>.'])]
